import{z as A,x as p,o as t,c as B,q as o,j as l,D as E,d as s,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"快照与克隆","description":"","frontmatter":{"title":"快照与克隆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fs-snapshots.md","filePath":"cs/fs-snapshots.md","lastUpdated":1791063341000}'),d={name:"cs/fs-snapshots.md"};function c(h,a,f,m,u,D){const r=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=o('<h1 id="快照与克隆" tabindex="-1">快照与克隆 <a class="header-anchor" href="#快照与克隆" aria-label="Permalink to &quot;快照与克隆&quot;">​</a></h1><div class="epigraph"><p>快照是多握一个旧根；克隆是从某根分出可写的新树，未改结点靠引用计数共享。</p><footer>—— 据 Rodeh 对 shadowing 与 clone 的分析；ZFS 与 btrfs 对 snapshot/clone 的接口整理</footer></div><p><a href="/cs/fs-checksum-scrub">上一课</a>保证旧块读出来可验证。<a href="/cs/cow-filesystem">COW</a> 已经能留下旧根。缺口是<strong>给用户的命名与可写分叉</strong>：快照只读、克隆可写、子卷如何从同一池里长出来。本课不把容器镜像层提前写成 overlay——那是接口课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>备份若拷贝整棵树，空间与时间都按容量计。COW 下「备份」可以是：原子记下当前根，引用计数加一。之后的写只碰新路径。克隆：对新根允许分配新叶，两边同时可写。缺口：何时增加计数、删除快照如何回收只被该根看见的块、以及与 <a href="/cs/fs-quota">配额</a> 后课的交叉（快照占用算谁的）。</p><p><span class="marginnote">快照可以想象成给整棵树拍「定格式存档」：不复制任何内容，只是把当前根的地址抄到另一张卡片上。之后的修改都走新路线，旧卡片指向的世界永远定格。</span></p><p><span class="marginnote">数字感受省了多少：对 1 TB 数据集建快照，通常只写几 KB（新根加计数），因为没有一个块被拷贝；之后改写 10 GB 独有数据，快照才新增约 10 GB——快照的「体积」只随你改了多少而涨，不随原数据集大小涨。</span></p><p><span class="marginnote">ZFS 的 snapshot 是只读数据集；clone 可写。btrfs 的 snapshot 默认可写，本质是新 subvolume。教学上区分「只读钉住」与「可写分叉」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建快照：事务中复制根指针，计数 +1，目录里出现新名字。写原数据集：COW 路径，不碰快照仍引用的结点。删除快照：从该根能到达、且计数降为零的块释放。发送/接收（ZFS send、btrfs send）把两根之间的差量化成流，这是机制上的增量备份，本课只点名。</p>',10)),(t(),l(i,null,{default:E(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E5%BD%93%E5%89%8D%E6%A0%B9%22%5D%20--%3E%20SNAP%5B%22%E5%8F%AA%E8%AF%BB%E5%BF%AB%E7%85%A7%E6%A0%B9%22%5D%0A%20%20ROOT%20--%3E%20CLONE%5B%22%E5%8F%AF%E5%86%99%E5%85%8B%E9%9A%86%E6%A0%B9%22%5D%0A%20%20SNAP%20--%3E%20SHARE%5B%22%E5%85%B1%E4%BA%AB%E6%9C%AA%E6%94%B9%E7%BB%93%E7%82%B9%22%5D%0A%20%20CLONE%20--%3E%20SHARE%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"快照把时间变成树的额外入口，而不是 LVM 那层块设备的写时复制（虽然 dm-snapshot 也是 COW，对象是块设备不是 FS 树）。与 FAT/ext2 对照：那些布局没有便宜的旧根。不要把本课写成量化栏的快照订单簿。LVM 快照在存储栈后课；这里的粒度是文件树。",-1)),a[5]||(a[5]=e("p",null,[s("读快照走旧根，"),e("a",{href:"/cs/page-cache"},"页缓存"),s(" 必须按 (inode 世代 / subvol) 区分，不能把克隆后的脏页当成快照内容。")],-1)),(t(),l(i,null,{default:E(()=>[n(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEL%5B%22%E5%88%A0%E9%99%A4%E5%BF%AB%E7%85%A7%E6%A0%B9%22%5D%20--%3E%20WALK%5B%22%E9%81%8D%E5%8E%86%E8%AF%A5%E6%A0%B9%E5%BC%95%E7%94%A8%E7%9A%84%E5%9D%97%22%5D%0A%20%20WALK%20--%3E%20RC%7B%22%E5%BC%95%E7%94%A8%E8%AE%A1%E6%95%B0%E9%99%8D%E4%B8%BA%E9%9B%B6%3F%22%7D%0A%20%20RC%20--%3E%7C%22%E6%98%AF%EF%BC%9A%E4%BB%85%E6%AD%A4%E5%BF%AB%E7%85%A7%E5%8F%AF%E8%A7%81%22%7C%20FREE%5B%22%E9%87%8A%E6%94%BE%E5%9D%97%E5%9B%9E%E6%B1%A0%22%5D%0A%20%20RC%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E5%8E%9F%E6%95%B0%E6%8D%AE%E9%9B%86%E4%BB%8D%E5%BC%95%E7%94%A8%22%7C%20KEEP%5B%22%E4%BF%9D%E7%95%99%E5%85%B1%E4%BA%AB%E5%9D%97%22%5D%0A%20%20FREE%20--%3E%20SPACE%5B%22%E7%A9%BA%E9%97%B4%E5%8F%AF%E5%86%8D%E5%88%86%E9%85%8D%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">这张图回答「删快照到底删了什么」：初学者容易以为只是删个名字——真正的工作是反向遍历该根，只有引用计数降为零、即仅被这个快照看见的块才真正回池；原数据集还在用的共享块必须留下。</span></p><p>实现上：可写快照与克隆在实现上常是同一套加根，只读只是权限。发送增量依赖两根能算差集；若重写同一逻辑块多次，发送流仍只含最后版本相对基线的差。 读法上只引用<a href="/cs/fs-checksum-scrub">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>快照与克隆</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证任意 POSIX 语义下 rename 与快照的每一种竞态都有发行版级描述。不引入 overlayfs 的 lower/upper——下一课序才是接口。下一课回到「不 COW 也能尽量保持一致」：软更新如何在原地更新里排序缓冲。</p><p>版本字段会变，课序钉的是机制对象「快照与克隆」，不是某一主线内核的结构体名。 后课默认：历史根可命名、可共享块。若坚持 FFS 原地更新，用依赖序代替日志与 COW，下一课软更新。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>快照加根；克隆可写分叉；共享靠计数。</li><li>回收是计数降零的块，不是删名字本身。</li><li>软更新是下一课的对照缺口。</li><li>出处：Rodeh, TOS 2008；McKusick；ZFS/btrfs 手册中的 snapshot。</li></ul>',9))])}const S=A(d,[["render",c]]);export{F as __pageData,S as default};
